<script setup>
import { computed, reactive, ref } from 'vue';
import MButton from '../../../components/mds/MButton.vue';
import MDialog from '../../../components/mds/MDialog.vue';
import MInput from '../../../components/mds/MInput.vue';
import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue';
import MSelect from '../../../components/mds/MSelect.vue';
import { toPeopleCreateDraft, toPeopleCreatePayload, validatePeopleEditDraft } from '../domain/people-write.mjs';

const props = defineProps({ organizations: { type: Array, default: () => [] }, saving: { type: Boolean, default: false }, serverError: { type: String, default: '' }, safeAreaStyle: { type: Object, default: () => ({}) } });
const emit = defineEmits(['cancel', 'save']); const draft = reactive(toPeopleCreateDraft()); const errors = reactive({}); const discard = ref(false); const initialDraft = JSON.stringify(draft);
const levels = ['', 'Lãnh đạo', 'Quản lý', 'Chuyên viên', 'Phóng viên', 'Khác'].map((value) => ({ value, label: value || 'Chọn cấp bậc' })); const categories = ['', 'VIP', 'Thường', 'Khác'].map((value) => ({ value, label: value || 'Chọn nhóm' })); const statuses = ['Đang hoạt động', 'Tạm ngừng', 'Ngừng hợp tác'].map((value) => ({ value, label: value })); const isDirty = computed(() => JSON.stringify(draft) !== initialDraft);
function validate() { const next = { ...validatePeopleEditDraft(draft) }; if (!Number.isInteger(Number(draft.org_id)) || Number(draft.org_id) < 1) next.org_id = 'Cơ quan là bắt buộc.'; Object.keys(errors).forEach((key) => delete errors[key]); Object.assign(errors, next); return next; }
function requestCancel() { if (props.saving) return; if (isDirty.value) { discard.value = true; return; } emit('cancel'); }
function submit() { if (Object.keys(validate()).length) return; emit('save', toPeopleCreatePayload(draft)); }
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Thêm nhân sự" @back="requestCancel"><template #actions><MButton variant="link" :disabled="saving" @click="requestCancel">Hủy</MButton></template></MMobileTopBar><form class="flex min-h-0 flex-1 flex-col" novalidate @submit.prevent="submit"><div class="min-h-0 flex-1 overflow-y-auto"><p class="mds-mobile-gutter-x border-b border-[var(--mds-border-light)] py-3 text-[13px] text-[var(--mds-text-secondary)]">Chỉ nhập thông tin công việc ban đầu; dữ liệu cá nhân quản lý ở luồng riêng.</p><div class="mds-mobile-gutter-x space-y-4 py-4"><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Họ và tên <span class="text-[var(--mds-danger)]">*</span></span><MInput v-model="draft.full_name" placeholder="Nhập họ và tên" :error="errors.full_name" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Cơ quan <span class="text-[var(--mds-danger)]">*</span></span><MSelect v-model="draft.org_id" :options="organizations" placeholder="Chọn cơ quan" :error="errors.org_id" :disabled="saving || !organizations.length" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Cấp bậc</span><MSelect v-model="draft.level" :options="levels" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Chức vụ</span><MInput v-model="draft.position" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Mảng phụ trách</span><MInput v-model="draft.beat" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Nhóm</span><MSelect v-model="draft.category" :options="categories" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Điểm quan hệ</span><MInput v-model="draft.relationship_score" type="number" min="0" max="100" placeholder="0–100" :error="errors.relationship_score" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.status" :options="statuses" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Email công việc</span><MInput v-model="draft.email_work" type="email" :disabled="saving" /></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Điện thoại công việc</span><MInput v-model="draft.phone_work" :disabled="saving" /></label><p v-if="serverError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ serverError }}</p></div></div><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" :disabled="saving" @click="submit">Tạo nhân sự</MButton></footer></form><MDialog v-model="discard" title="Bỏ nhân sự mới?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
